  "is_atomic": true,
  "atomic_questions": [
    "Is the objective to maximize total profit (total revenue from all produced units minus total processing cost and total raw material cost), or is it to minimize total cost, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

